#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-fail-a-test-on-mail-to-another-domain. Do not edit.
set -e
cd "$(dirname "$0")"
cat > invoice.eml <<'EOF'
From: billing@example.com
To: ann@example.com
Subject: Your invoice

Invoice 1042 is attached.
EOF
cat > cc-outside.eml <<'EOF'
From: billing@example.com
To: ann@example.com
Cc: carol@elsewhere.org
Subject: Your invoice

Invoice 1043 is attached.
EOF
cat > wait-for-log.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Waits, at most ten seconds, until the log holds <count> lines with <text>, then prints them
# without their exchange numbers. Exit 1 if they never come.
# Usage: sh wait-for-log.sh <text> <count> <log file>
tries=0
until [ "$(grep -c -F -- "$1" "$3")" -ge "$2" ]; do
  tries=$((tries + 1))
  [ "$tries" -ge 10 ] && exit 1
  sleep 1
done
grep -F -- "$1" "$3" | sed 's/^#[0-9]* //'
EOF
surl -v --log-file surl.log --mail-domain example.com --mail-domain example.org --mailbox billing@example.com:billpass --mailbox ann@example.com:annpass --mailbox sales@example.org:salespass smtp://127.0.0.1:8080/ pop3://127.0.0.1:8081/ &
sleep 1
curl -s -S --crlf -u billing@example.com:billpass --mail-from billing@example.com --mail-rcpt carol@elsewhere.org -T invoice.eml smtp://127.0.0.1:8080/app.example.com || true
kill $(jobs -p)
